247	// ---------- Port forwarding (firewall/networking) ----------
248	
249	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
250	const MAX_FORWARDS_PER_SERVER = 10;
251	
252	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
253	  const serverId = String(formData.get("serverId") ?? "");
254	  const { user, server } = await ownedServer(serverId);
255	  const parsed = z
256	    .object({
257	      guestPort: z.coerce.number().int().min(1).max(65535),
258	      protocol: z.enum(["tcp", "udp"]),
259	    })
260	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
261	  if (!parsed.success) return { error: "Invalid port." };
262	
263	  const count = await db.portForward.count({ where: { serverId } });
264	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
265	
266	  // Allocate the public port with the DB as the arbiter, not this read.
267	  //
268	  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
269	  // from a snapshot read and inserting it unguarded meant two requests that
270	  // overlapped — a double-click, or two customers adding a forward at the same
271	  // moment — both picked the same lowest free port and the loser's insert threw
272	  // a raw Prisma P2002. That exception escaped this action, so the customer got
273	  // a server-error page instead of a message, and (in production, where Next
274	  // redacts action errors) no clue what happened or that simply retrying works.
275	  //
276	  // Retry across the next few free candidates so an ordinary collision resolves
277	  // itself silently, and turn a genuine exhaustion into an honest, actionable
278	  // message rather than a crash.
279	  const used = new Set([
280	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
281	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
282	  ]);
283	  const candidates: number[] = [];
284	  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
285	    if (!used.has(p)) candidates.push(p);
286	  }
287	  if (candidates.length === 0) {
288	    return {
289	      error:
290	        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
291	        "Delete a forward you no longer need, or contact support to have the pool widened.",
292	    };
293	  }
294	
295	  let publicPort = 0;
296	  for (const candidate of candidates) {
297	    try {
298	      await db.portForward.create({
299	        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
300	      });
301	      publicPort = candidate;
302	      break;
303	    } catch (e: any) {
304	      // P2002 = another request took this port between our read and this insert.
305	      // Anything else is a real failure and must not be swallowed.
306	      if (e?.code !== "P2002") throw e;
307	    }
308	  }
309	  if (!publicPort) {
310	    return {
311	      error:
312	        "Another request took the public port we picked, several times in a row. " +
313	        "Nothing was created — please try adding the forward again.",
314	    };
315	  }
316	
317	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
318	  await db.auditLog.create({
319	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
320	  });
321	  revalidatePath(`/dashboard/servers/${serverId}`);
322	  return {};
323	}
324	
325	export async function deletePortForward(serverId: string, forwardId: string) {
326	  const { user } = await ownedServer(serverId);
327	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
328	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
329	  await db.auditLog.create({
330	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
331	  });
332	  revalidatePath(`/dashboard/servers/${serverId}`);
333	}
