22	async function ensureChain() {
23	  try {
24	    await iptables(["-t", "nat", "-N", CHAIN]);
25	  } catch {
26	    /* chain exists */
27	  }
28	  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
29	  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
30	  try {
31	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
32	  } catch {
33	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
34	  }
35	  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
36	  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
37	  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
38	  // issuance, migration remediation, backups, the Claude backfill — were hitting
39	  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
40	  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
41	  // public IP is redirected; host-local :port traffic to anything else is
42	  // untouched, and the shared DNAT rules only match ports that actually forward.
43	  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
44	  if (publicIp) {
45	    try {
46	      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
47	    } catch {
48	      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
49	    }
50	  }
51	}
