53	/**
54	 * The real, iptables-backed NatHost — the only implementation production uses.
55	 * The decision logic it is handed to lives in lib/nat-rules.ts and is tested
56	 * against an in-memory fake; see the H5 incident note at the top of that file.
57	 */
58	function iptablesHost(): NatHost {
59	  return {
60	    ensureChain,
61	    listChain: async () => {
62	      const { stdout } = await exec("iptables", ["-t", "nat", "-S", CHAIN]);
63	      return stdout;
64	    },
65	    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", CHAIN, ...ruleSpec(r)]),
66	    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", CHAIN, ...ruleSpec(r)]),
67	  };
68	}
69	
70	/**
71	 * Reconcile the NXEON_FWD chain with the database, and verify the result.
72	 *
73	 * This used to open with `iptables -t nat -F NXEON_FWD` and rebuild the chain in
74	 * an unguarded loop, so a single failed `-A` aborted the rebuild and left every
75	 * subsequent server with no DNAT rule — a fleet-wide SSH blackhole that reported
76	 * DONE, because DONE meant "the last iptables call exited 0" (incident H5).
77	 *
78	 * There is no flush now. `reconcileNatChain` reads the chain, applies only the
79	 * difference, then reads it BACK and throws with the exact missing rules and the
80	 * command to inspect them if the kernel does not hold what the database says it
81	 * should. Rules that were already correct are never removed, so no failure in
82	 * this path can take down a customer who was working before it ran.
83	 *
84	 * Throws on an unproven ruleset — callers that cannot tolerate a throw must say
85	 * so; `remove()` in worker/index.ts calls this after deleting the server row, so
86	 * a throw there re-queues DELETE onto a row that no longer exists. That caller
87	 * uses `syncPortForwardsBestEffort` below.
88	 */
89	export async function syncPortForwards(): Promise<NatSyncResult> {
90	  const servers = await db.server.findMany({
91	    where: {
92	      ipAddress: { not: null },
93	      sshPort: { not: null },
94	      status: { notIn: ["SUSPENDED", "DELETING"] },
95	    },
96	    include: { portForwards: true },
97	  });
98	
99	  const intent = planNatRules(servers as unknown as ForwardSource[]);
100	
101	  // Two data problems that used to be invisible because the old loop just built
102	  // whatever it was handed. Neither blocks the sync — the ruleset we install is
103	  // still verified end to end — but neither is swallowed either.
104	  for (const c of intent.conflicts) {
105	    console.error(
106	      `[nat] port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
107	        `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
108	    );
109	  }
110	  for (const r of intent.rejected) {
111	    console.error(`[nat] ${r.hostname}: no rule installed — ${r.reason}`);
112	  }
113	
114	  const result = await reconcileNatChain(iptablesHost(), CHAIN, intent);
115	  if (result.unparsed.length) {
116	    console.warn(
117	      `[nat] ${CHAIN} contains ${result.unparsed.length} rule(s) this engine did not write and ` +
118	        `will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
119	    );
120	  }
121	  console.log(
122	    `[nat] ${CHAIN} verified: ${result.verified} rule(s) present (+${result.added} / -${result.deleted})`
123	  );
124	  return result;
125	}
126	
127	/**
128	 * For callers that must not be re-queued by a sync failure (server DELETE runs
129	 * this after the row is gone, so a throw dies on "Server not found" on retry and
130	 * the sync is never re-attempted — H5's aggravating factor).
131	 *
132	 * It still never claims success: the failure is logged in full and returned, so
133	 * the caller can surface it. What it will not do is convert a networking problem
134	 * into a stuck job that hides it.
135	 */
136	export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
137	  try {
138	    await syncPortForwards();
139	    return null;
140	  } catch (e: any) {
141	    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
142	    return e instanceof Error ? e : new Error(String(e));
143	  }
144	}
