33	/**
34	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
35	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
36	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
37	 * this it existed only as a copy of the same number hardcoded on the IP page.
38	 */
39	export const OVH_IP_UNIT_COST_CENTS = 239;
40	
41	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
42	/**
43	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
44	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
45	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
46	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
47	 */
48	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
49	
50	/**
51	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
52	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
53	 * every order/renewal/display path so they can never disagree.
54	 *
55	 * NORMALISED to a non-negative whole number of cents, exactly as
56	 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
57	 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
58	 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
59	 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
60	 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
61	 * row — every one of which is integer cents. A fractional setting produced a
62	 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
63	 * to it; a negative one silently discounted the plan.
64	 */
65	export async function dedicatedIpMonthlyCents(): Promise<number> {
66	  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
67	  return Math.max(0, Math.round(v));
68	}
69	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
