72	/** OVH failover gateway = the host's /24 gateway (…​.254). */
73	export function ovhGateway(): string {
74	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
75	  const parts = ip.split(".");
76	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
