79	/**
80	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
81	 * upsert them into the pool. The host's own primary IP is never poolable.
82	 */
83	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
84	  if (SANDBOX) return { imported: 0, total: 0 };
85	  if (!ovhConfigured()) return { imported: 0, total: 0 };
86	  const primary = process.env.PUBLIC_IP;
87	  const blocks: string[] = await ovhApi.ips();
88	  let imported = 0;
89	  for (const block of blocks) {
90	    if (block.includes(":")) continue; // IPv6 handled separately
91	    let info: any;
92	    try {
93	      info = await ovhApi.ipInfo(block);
94	    } catch {
95	      continue;
96	    }
97	    if (info?.routedTo?.serviceName !== SERVER) continue;
98	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
99	    // A /32 block is a single usable IP == the block minus the mask.
100	    const address = block.split("/")[0];
101	    if (address === primary) continue;
102	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
103	    if (!existing) {
104	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
105	      // in active use by SOME VM — possibly one this app never created a Server
106	      // row for (e.g. internal infrastructure provisioned directly via the OVH
107	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
108	      // yet. Importing it as FREE anyway let a real customer server collide with
109	      // an unrelated VM's network identity — never assign an IP that's already
110	      // claimed at the network layer, regardless of whether our DB knows about it.
111	      if (await findVirtualMacForIp(address)) continue;
112	      if (await hasLiveDnatRule(address)) continue;
113	      // Every IP this function imports is, by construction, a spare address
114	      // OVH says is routed to us and not yet claimed at the network layer — the
115	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
116	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
117	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
118	      // to tell them apart from a genuinely free customer IP and must not try —
119	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
120	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE", purpose: "CUSTOMER" } });
121	      imported++;
122	    }
123	  }
124	  const total = await db.dedicatedIp.count();
125	  return { imported, total };
126	}
