128	/** Count of IPs actually available to hand to a customer — same eligibility as
129	 * allocateDedicatedIp's claim query; excludes admin-marked INTERNAL rows. */
130	export async function freeCount(): Promise<number> {
131	  return db.dedicatedIp.count({ where: { status: "FREE", purpose: "CUSTOMER" } });
132	}
