134	/**
135	 * The real, live monthly OVH bill for the whole dedicated-IP pool, in cents —
136	 * every pooled IP (free or assigned) costs OVH the same per-IP rate regardless
137	 * of whether a customer is using it. Consumed by the Accounting dashboard as an
138	 * automatic recurring INFRASTRUCTURE expense line so this cost is never
139	 * hand-typed and can never drift from what /admin/ips itself shows.
140	 */
141	export async function dedicatedIpPoolMonthlyCostCents(): Promise<number> {
142	  const total = await db.dedicatedIp.count();
143	  return total * OVH_IP_UNIT_COST_CENTS;
