146	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
147	async function findVirtualMacForIp(address: string): Promise<string | null> {
148	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
149	  for (const m of macs) {
150	    const ips: string[] = await ovh(
151	      "GET",
152	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
153	    ).catch(() => []);
154	    if (ips.includes(address)) return m;
155	  }
156	  return null;
157	}
