237	/** Set reverse DNS (PTR) for a dedicated IP. */
238	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
239	  if (!ovhConfigured()) return;
240	  await ovhApi.setReverse(`${address}/32`, address, reverse);
241	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
242	}
