75	    try {
76	      obj = JSON.parse(raw);
77	    } catch {
78	      return null;
79	    }
80	  }
81	  if (!obj || typeof obj !== "object") return null;
82	  const { chargeCents } = obj as Record<string, unknown>;
83	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
