87	export type GameOrderQuote = {
88	  gamePlanId: string;
89	  gameFamily: string;
90	  planName: string;
91	  basePlanId: string;
92	  osTemplateId: string;
93	  /** Normalised term (1 or 12). */
94	  term: number;
95	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
96	  annualPct: number;
97	  /** DB-fed per-month base (priceCents / termMonths). */
98	  monthlyCents: number;
