73	export type DiskExpandQuote = {
74	  server: QuotedServer;
75	  /** GB being added in THIS purchase. */
76	  addGB: number;
77	  /** `extraDiskGB` the server will hold once the worker finishes. */
78	  targetExtraDiskGB: number;
79	  /** Effective disk (plan + extra) after the expansion. */
80	  newTotalDiskGB: number;
81	  perGbCents: number;
82	  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
83	  monthlyCents: number;
84	  /** One-off charge for the remainder of the CURRENT paid term. */
85	  prorateCents: number;
