88	/**
89	 * Validate an expansion and compute the prorated charge over the ACTUAL
90	 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
91	 * remaining month; null expiresAt on free/admin servers => 0). Throws
92	 * DiskExpandError with a user-facing message on any guard failure. Does NOT
93	 * check ownership — callers must do that.
94	 */
95	export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
96	  const server = await loadServer(serverId);
97	  if (!server) throw new DiskExpandError("Not found");
98	  if (!isValidExtraDiskAddGB(addGB)) {
99	    throw new DiskExpandError(
100	      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
101	    );
102	  }
103	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
104	    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
105	  }
106	  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");
107	
108	  const targetExtraDiskGB = server.extraDiskGB + addGB;
