344	/**
345	 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
346	 * directly (no wallet pre-fund), applying the customer's wallet balance to the
347	 * split. Structurally identical to createResizeCheckout: the CARD is charged only
348	 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
349	 * in metadata as `chargeCents`, so the confirm route debits the whole proration
350	 * back out of the wallet against the just-credited card amount. The wallet is
351	 * never touched before the card clears.
352	 *
353	 * Attaches a Stripe CUSTOMER and requests `setup_future_usage`, same rationale as
354	 * createResizeCheckout above: a disk expansion can be a customer's first-ever card
355	 * charge, and it must not be the one purchase this codebase forgets to save a card
356	 * for.
357	 */
358	export async function createDiskExpandCheckout(
359	  user: CardUser,
360	  cardCents: number,
361	  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
362	): Promise<EmbeddedCheckout | null> {
363	  if (!stripeConfigured() || cardCents <= 0) return null;
364	  const base = process.env.APP_URL ?? "http://localhost:3000";
365	  const { ensureStripeCustomer } = await import("./stripe-cards");
366	  const customerId = await ensureStripeCustomer(user);
367	  const session = await stripe().checkout.sessions.create({
368	    mode: "payment",
369	    customer: customerId,
370	    payment_intent_data: { setup_future_usage: "off_session" },
371	    line_items: [
372	      {
373	        price_data: {
374	          currency: "usd",
375	          product_data: {
376	            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
377	            // The one-way nature is on the Stripe page itself, not just in our UI.
378	            description: "Permanent storage expansion — disk space can be added but never removed.",
379	          },
380	          unit_amount: cardCents,
381	        },
382	        quantity: 1,
383	      },
384	    ],
385	    metadata: {
386	      nxeonUserId: user.id,
387	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
388	      nxeonDiskExpand: packMetadata("Disk expansion intent", {
389	        serverId: expand.serverId,
390	        addGB: expand.addGB,
391	        chargeCents: expand.prorateCents,
392	      }),
393	    },
394	    // Embedded modal on our page; return_url is the same fulfilling confirm route.
395	    ui_mode: EMBEDDED_UI_MODE,
396	    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
397	  }, EMBEDDED_REQUEST_OPTS);
398	  return session.client_secret
399	    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
400	    : null;
401	}
